const b = $json.body ?? $json;
const text = b.text || b.raw_text || (b.zip_manifest ? JSON.stringify(b.zip_manifest) : '') || '';
const category = (b.category || '').toLowerCase();
let itemType = b.item_type || (category === 'ideas' || category === 'idea' ? 'idea' : category === 'code' ? 'code' : category === 'apps' || category === 'app' ? 'app' : category === 'research' ? 'research' : category === 'photos' || category === 'photo' ? 'photo' : category === 'screenshots' || category === 'screenshot' ? 'screenshot' : category === 'documents' || category === 'document' ? 'document' : category === 'outreach' || category === 'prospects' ? 'outreach' : 'unknown');
const title = b.title || b.filename || (text ? text.slice(0,120).replace(/\s+/g,' ') : 'Untitled Arc item');
const metadata = {...b};
delete metadata.binary_base64;
return [{json:{source:b.source||'webhook',source_ref:b.source_ref||b.message_id||null,item_type:itemType,title,raw_text:text,project_hint:b.project_hint||null,content_sha256:b.sha256||null,chat_id:b.chat_id||null,user_id:b.user_id||null,username:b.username||null,binary_base64:b.binary_base64||null,metadata}}];

let raw = $json.message?.content ?? $json.response ?? $json;
let parsed;
try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { parsed = {parse_error:e.message, raw:String(raw)}; }
return [{json:{...parsed, _raw: raw}}];

